	// Backend-native VkImageLayout value left after rendering succeeds, such as
	// VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL. Required, so
	// VK_IMAGE_LAYOUT_UNDEFINED is invalid.
