//export mlnGo_mln_runtime_event_handler_callback
func mlnGo_mln_runtime_event_handler_callback(native_user_data unsafe.Pointer, native_events *C.mln_event_batch_view) {
	defer func() {
		if failure := recover(); failure != nil {
			bindingReportCallbackPanic("mln_runtime_event_callback", failure)
		}
	}()
	callbacks, ok := bindingCallbackValue[RuntimeEventHandler](native_user_data)
	if !ok || callbacks.Callback == nil {
		return
	}
	callbacks.Callback(func() []RuntimeEvent {
		length := bindingLength(uint64((*native_events).event_count))
		result := make([]RuntimeEvent, length)
		for i := range result {
			item := *(*C.mln_runtime_event)(bindingElement(unsafe.Pointer((*native_events).events), i, uint64((*native_events).event_size), unsafe.Sizeof(*(*native_events).events), unsafe.Alignof(*(*native_events).events)))
			result[i] = copyRuntimeEvent(item)
		}
		return result
	}())
	return
}

//export mlnGo_mln_http_header_transform_callback
